namespace SmartParking.Domain.Common;

/// <summary>
/// Root of a consistency boundary. Collects the domain events raised by a change; the unit of work
/// dequeues them on save and writes one outbox message and one audit entry per event (spec 001).
/// </summary>
public abstract class AggregateRoot
{
    private readonly List<IDomainEvent> domainEvents = [];

    /// <summary>UUID v7, generated by the application from the injected <c>TimeProvider</c>.</summary>
    public Guid Id { get; protected init; }

    public IReadOnlyCollection<IDomainEvent> DomainEvents => domainEvents.AsReadOnly();

    /// <summary>Returns the pending events and clears them, so a second save does not repeat them.</summary>
    public IReadOnlyList<IDomainEvent> DequeueDomainEvents()
    {
        IDomainEvent[] pending = [.. domainEvents];
        domainEvents.Clear();
        return pending;
    }

    protected void Raise(IDomainEvent domainEvent)
    {
        ArgumentNullException.ThrowIfNull(domainEvent);
        domainEvents.Add(domainEvent);
    }
}
